// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 amount) public {
        amount = bound(amount, 0, type(uint128).max);
        vm.deal(actor, amount);
        uint256 before = c.getBalance(actor);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 afterBal = c.getBalance(actor);
        assertTrue(afterBal >= before);
    }
}
